package com.logplatform.alert.web;
import com.logplatform.alert.domain.IncidentEntity; import java.time.Instant;
public record IncidentResponse(Long id,Long tenantId,Long ruleId,String fingerprint,String status,String title,String description,Instant firstSeenAt,Instant lastSeenAt,long occurrenceCount,String acknowledgedBy,String assignedTo,Instant resolvedAt){public static IncidentResponse from(IncidentEntity i){return new IncidentResponse(i.getId(),i.getTenantId(),i.getRuleId(),i.getFingerprint(),i.getStatus(),i.getTitle(),i.getDescription(),i.getFirstSeenAt(),i.getLastSeenAt(),i.getOccurrenceCount(),i.getAcknowledgedBy(),i.getAssignedTo(),i.getResolvedAt());}}
